    void toggleFavorite(Catalog.Item item){Set<String> ids=favorites();boolean added=ids.add(item.id);if(!added)ids.remove(item.id);prefs.edit().putStringSet("favorites",ids).putString("saved:"+item.id,item.raw.toString()).apply();message(added?"Added to watchlist":"Removed from watchlist");if(!detailsOpen)render();}
    void watch(Catalog.Item item){if(item.type.equals("manga")){chapters(item,0);return;}if(item.type.equals("series")){seasons(item);return;}if(item.type.equals("live")){status.setText("Finding event streams…");io.execute(()->{try{JSONArray rows=ContentApi.liveStreams(item);ui.post(()->{if(!isDestroyed()){status.setText("Today's sports");chooseStreams(item,rows,item.id);}});}catch(Exception e){ui.post(()->message("Live source is currently unavailable"));}});return;}
        JSONArray streams=item.streams();if(item.id.matches("tmdb-movie-[0-9]+"))try{streams=ContentApi.movieSources(item.id.substring("tmdb-movie-".length()),"movie",1,1);}catch(Exception ignored){}chooseStreams(item,streams,item.id);}
    void seasons(Catalog.Item item){
        if(!item.id.matches("tmdb-series-[0-9]+")){message("Invalid TMDB series ID");return;}String id=item.id.substring("tmdb-series-".length()),key=tmdbKey();status.setText("Loading TMDB seasons…");
        io.execute(()->{try{JSONArray seasons=ContentApi.seasons(id,key);List<JSONObject> available=new ArrayList<>();for(int i=0;i<seasons.length();i++){JSONObject season=seasons.getJSONObject(i);if(season.optInt("episode_count")>0)available.add(season);}
            ui.post(()->{if(isDestroyed())return;status.setText("TMDB");if(available.isEmpty()){message("No episodes listed yet");return;}String[] labels=new String[available.size()];for(int i=0;i<labels.length;i++)labels[i]=available.get(i).optString("name","Season "+available.get(i).optInt("season_number"));
                new AlertDialog.Builder(this).setTitle(item.title).setItems(labels,(d,n)->loadSeason(item,id,available.get(n).optInt("season_number"),key)).setNegativeButton("Close",null).show();});
        }catch(Exception e){ui.post(()->{if(!isDestroyed()){status.setText("TMDB season service unavailable");try{chooseStreams(item,ContentApi.movieSources(id,"tv",1,1),item.id+":s1e1");}catch(JSONException ignored){}}});}});
    }
    void loadSeason(Catalog.Item item,String id,int number,String key){
        status.setText("Loading TMDB episodes…");io.execute(()->{try{JSONArray episodes=ContentApi.seasonEpisodes(id,number,key);ui.post(()->{if(isDestroyed())return;status.setText("TMDB");if(episodes.length()==0){message("No episodes listed yet");return;}String[] labels=new String[episodes.length()];for(int i=0;i<labels.length;i++){JSONObject ep=episodes.optJSONObject(i);labels[i]="Episode "+ep.optInt("episode")+" · "+ep.optString("title");}
            new AlertDialog.Builder(this).setTitle(number==0?"Specials":"Season "+number).setItems(labels,(d,n)->{JSONObject ep=episodes.optJSONObject(n);try{chooseStreams(item,ContentApi.movieSources(id,"tv",number,ep.optInt("episode")),item.id+":"+ep.optString("id"));}catch(JSONException ignored){}}).setNegativeButton("Close",null).show();});
        }catch(Exception e){ui.post(()->{if(!isDestroyed())message("Episode service unavailable. Try again later.");});}});
    }
    void episodeList(Catalog.Item item,JSONArray episodes){TreeSet<Integer> numbers=new TreeSet<>();for(int i=0;i<episodes.length();i++){JSONObject ep=episodes.optJSONObject(i);if(ep!=null)numbers.add(ep.optInt("season",1));}if(numbers.isEmpty()){message("No episodes available");return;}Integer[] seasons=numbers.toArray(new Integer[0]);String[] labels=new String[seasons.length];for(int i=0;i<labels.length;i++)labels[i]=seasons[i]==0?"Specials":"Season "+seasons[i];new AlertDialog.Builder(this).setTitle(item.title).setItems(labels,(d,index)->{List<JSONObject> selected=new ArrayList<>();for(int i=0;i<episodes.length();i++){JSONObject ep=episodes.optJSONObject(i);if(ep!=null&&ep.optInt("season",1)==seasons[index])selected.add(ep);}String[] titles=new String[selected.size()];for(int i=0;i<titles.length;i++)titles[i]="Episode "+selected.get(i).optInt("episode",i+1)+" · "+selected.get(i).optString("title","Episode");new AlertDialog.Builder(this).setTitle(labels[index]).setItems(titles,(dialog,n)->{JSONObject ep=selected.get(n);JSONArray sources=ep.optJSONArray("streams");if(item.id.matches("tmdb-series-[0-9]+"))try{sources=ContentApi.movieSources(item.id.substring("tmdb-series-".length()),"tv",ep.optInt("season",1),ep.optInt("episode",1));}catch(Exception ignored){}chooseStreams(item,sources,item.id+":"+ep.optString("id"));}).setNegativeButton("Close",null).show();}).setNegativeButton("Close",null).show();}
    void chapters(Catalog.Item item,int offset){status.setText("Loading English chapters…");io.execute(()->{try{JSONArray data=ContentApi.chapters(item.raw.getString("mangaId"),offset);List<JSONObject> rows=new ArrayList<>();for(int i=0;i<data.length();i++){JSONObject chapter=data.getJSONObject(i);String external=chapter.getJSONObject("attributes").optString("externalUrl");if(external.isEmpty()||external.startsWith("https://"))rows.add(chapter);}ui.post(()->{if(isDestroyed())return;status.setText("MangaDex · English chapters");if(rows.isEmpty()){message("No readable English chapters in this page");return;}String[] labels=new String[rows.size()];for(int i=0;i<labels.length;i++){JSONObject a=rows.get(i).optJSONObject("attributes");labels[i]="Chapter "+a.optString("chapter","Special")+" · "+a.optString("title","")+(a.optString("externalUrl").isEmpty()?"":" · Publisher reader");}AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle(item.title).setItems(labels,(d,n)->{JSONObject chapter=rows.get(n);String external=chapter.optJSONObject("attributes").optString("externalUrl");if(external.isEmpty())startActivity(new Intent(this,MangaReaderActivity.class).putExtra("chapter",chapter.optString("id")).putExtra("parent",item.id));else startActivity(new Intent(this,BrowserPlayerActivity.class).putExtra("url",external).putExtra("reader",true).putExtra("title",item.title));}).setNegativeButton("Close",null);if(data.length()==100)dialog.setNeutralButton("Older chapters",(d,n)->chapters(item,offset+100));dialog.show();});}catch(Exception e){ui.post(()->{if(!isDestroyed()){status.setText("MangaDex");message("Chapter service unavailable");}});}});}
    void chooseStreams(Catalog.Item item,JSONArray sources,String key){
        if(sources==null||sources.length()==0){message("No playback sources available right now");return;}
        if(sources.length()==1){openStream(item,sources.optJSONObject(0),key);return;}
        if(item.id.startsWith("tmdb-")&&sources.length()==PlaybackSources.IDS.length){openStream(item,sources.optJSONObject(PlaybackSources.index(selectedPlaybackSource())),key);return;}
        String[] labels=new String[sources.length()];for(int i=0;i<labels.length;i++)labels[i]=sources.optJSONObject(i)==null?"Unavailable":sources.optJSONObject(i).optString("label","Stream "+(i+1));
        new AlertDialog.Builder(this).setTitle("Choose playback source").setSingleChoiceItems(labels,PlaybackSources.index(selectedPlaybackSource()),(d,n)->{if(n<PlaybackSources.IDS.length)prefs.edit().putString("playbackSource",PlaybackSources.IDS[n]).apply();d.dismiss();openStream(item,sources.optJSONObject(n),key);}).setNegativeButton("Cancel",null).show();
    }
    void openStream(Catalog.Item item,JSONObject source,String key){
        if(source==null)return;if(source.optString("provider").equals("rawcast")){if(!prefs.getBoolean("rawcastPlayback",false)){message("Enable RawCast playback in Settings first.");return;}if(!RawCast.get(this).hasKey()){message("RawCast requires your API key. Streaming uses your limited API quota.");rawcastSettings();return;}message("RawCast · Streaming uses your limited API quota. Resolving…");io.execute(()->{try{JSONObject media=RawCast.get(this).stream(source.optString("type"),source.optString("tmdb"),source.optInt("season",1),source.optInt("episode",1));media.put("tmdb",source.optString("tmdb")).put("type",source.optString("type")).put("season",source.optInt("season",1)).put("episode",source.optInt("episode",1));ui.post(()->{if(!isDestroyed())openStream(item,media,key);});}catch(Exception e){ui.post(()->message(e.getMessage()));}});return;}try{URL u=new URL(source.optString("url"));if(!u.getProtocol().equals("https"))throw new Exception();}catch(Exception e){message("Invalid playback source");return;}
        prefs.edit().putString("saved:"+item.id,item.raw.toString()).putLong("watchedAt:"+item.id,System.currentTimeMillis()).apply();history.started(item,key);
        if(source.optBoolean("embed")){if(prefs.getLong("position:"+item.id,0)<=0)prefs.edit().putLong("position:"+item.id,1).apply();String address=source.optString("url");long position=prefs.getLong("position:"+key,0),duration=prefs.getLong("duration:"+key,0);if(position>30000&&(duration<=0||position<duration*.95)){String host=android.net.Uri.parse(address).getHost();if("vidstuck.xyz".equals(host)||"vidsrc.sh".equals(host))address+=(address.contains("?")?"&":"?")+("vidsrc.sh".equals(host)?"startAt":"progress")+"="+(position/1000);};startActivity(new Intent(this,BrowserPlayerActivity.class).putExtra("url",address).putExtra("title",item.title).putExtra("parent",item.id).putExtra("key",key));}
        else startActivity(new Intent(this,PlayerActivity.class).putExtra("stream",source.toString()).putExtra("title",item.title).putExtra("key",key).putExtra("parent",item.id).putExtra("live",item.type.equals("live")).putExtra("tmdb",source.optString("tmdb")).putExtra("mediaType",source.optString("type")).putExtra("season",source.optInt("season",0)).putExtra("episode",source.optInt("episode",1)));
    }

