    void homePanelSettings(){Set<String> current=new HashSet<>(prefs.getStringSet("homePanels",HomePanels.defaults()));boolean[] checked=new boolean[HomePanels.IDS.length];for(int i=0;i<checked.length;i++)checked[i]=current.contains(HomePanels.IDS[i]);AlertDialog panels=new AlertDialog.Builder(this).setTitle("Homepage panels").setMultiChoiceItems(HomePanels.LABELS,checked,(d,n,on)->{if(on)current.add(HomePanels.IDS[n]);else current.remove(HomePanels.IDS[n]);}).setPositiveButton("Save",(d,n)->{prefs.edit().putStringSet("homePanels",current).apply();if(category.equals("Home"))render();}).setNeutralButton("Restore defaults",(d,n)->{prefs.edit().remove("homePanels").apply();if(category.equals("Home"))render();}).setNegativeButton("Cancel",null).create();panels.setOnShowListener(d->{panels.getWindow().setBackgroundDrawable(shape(SURFACE,0));for(int which:new int[]{AlertDialog.BUTTON_POSITIVE,AlertDialog.BUTTON_NEGATIVE,AlertDialog.BUTTON_NEUTRAL})panels.getButton(which).setTextColor(ACCENT);});panels.show();}
    private final Map<String,List<Catalog.Item>> homeExtras=new HashMap<>();private final Set<String> homeExtraLoading=new HashSet<>();
    void homeExtraRows(int token){for(int i=11;i<HomePanels.IDS.length;i++){String id=HomePanels.IDS[i],label=HomePanels.LABELS[i];if(!homePanel(id))continue;List<Catalog.Item> rows=homeExtras.get(id);if(rows!=null){posterRow(label,rows,token);continue;}if(!homeExtraLoading.add(id))continue;io.execute(()->{List<Catalog.Item> loaded;try{JSONObject data=id.equals("anime")?ContentApi.animeData(tmdbKey(),"tv",1):ContentApi.genreData(tmdbKey(),"movie",HomePanels.genre(id),1);loaded=ContentApi.tmdbRows(data.getJSONArray("results"),id.equals("anime")?"tv":"movie",false);}catch(Exception e){loaded=new ArrayList<>();}List<Catalog.Item> ready=loaded;ui.post(()->{homeExtraLoading.remove(id);homeExtras.put(id,ready);if(!isDestroyed()&&category.equals("Home"))render();});});}}
    String channelFavoriteKey(String section,M3uPlaylist.Channel c){try{byte[] digest=java.security.MessageDigest.getInstance("SHA-256").digest((section+"|"+c.name+"|"+c.group).getBytes("UTF-8"));StringBuilder b=new StringBuilder();for(byte v:digest)b.append(String.format(Locale.ROOT,"%02x",v&255));return b.toString();}catch(Exception e){throw new IllegalStateException(e);}}
    boolean channelFavorite(String section,M3uPlaylist.Channel c){return savedIds("liveFavorites").contains(channelFavoriteKey(section,c));}

    void libraryMenu(){new AlertDialog.Builder(this).setTitle("Your Space").setItems(new String[]{"Downloads","Watchlist","Continue watching","Plan to watch","Watch history","Search history","Collections"},(d,n)->{category=new String[]{"Downloads","Watchlist","Continue","Plan to watch","Watch history","Search history","Collections"}[n];collection="";++loadVersion;catalog=new ArrayList<>(browse);for(Map.Entry<String,?> e:prefs.getAll().entrySet())if(e.getKey().startsWith("saved:")&&e.getValue() instanceof String)try{Catalog.Item item=new Catalog.Item(new JSONObject((String)e.getValue()));boolean exists=false;for(Catalog.Item old:catalog)if(old.id.equals(item.id))exists=true;if(!exists)catalog.add(item);}catch(Exception ignored){}render();}).show();}
