    static final class GenreImageTask {final String type;final int id,token;final ImageView image;GenreImageTask(String type,int id,ImageView image,int token){this.type=type;this.id=id;this.image=image;this.token=token;}}
    void genrePicture(String type,int id,ImageView image,int token){
        String key=type+id,url=genreArtwork.get(key);
        if(url==null)for(Catalog.Item item:browse){if(!ContentApi.media(item).equals(type))continue;JSONArray genres=item.raw.optJSONArray("genreIds");if(genres==null)continue;for(int i=0;i<genres.length();i++)if(genres.optInt(i)==id){url=item.raw.optString("backdrop");if(url.isEmpty())url=item.poster;if(!url.isEmpty())break;}if(url!=null&&!url.isEmpty())break;}
        if(url!=null&&!url.isEmpty()){genreArtwork.put(key,url);picture(url,image,token);return;}
        pendingGenreArtwork.put(image,new GenreImageTask(type,id,image,token));image.post(()->ui.post(visiblePictures));
    }
    void loadVisibleGenreArtwork(){
        Rect visible=new Rect();Iterator<Map.Entry<ImageView,GenreImageTask>> iterator=pendingGenreArtwork.entrySet().iterator();List<GenreImageTask> tasks=new ArrayList<>();while(iterator.hasNext()){Map.Entry<ImageView,GenreImageTask> entry=iterator.next();GenreImageTask task=entry.getValue();if(task.token!=renderVersion){iterator.remove();continue;}if(entry.getKey().isShown()&&entry.getKey().getGlobalVisibleRect(visible)){tasks.add(task);iterator.remove();}}
        for(GenreImageTask task:tasks){String key=task.type+task.id;String cached=genreArtwork.get(key);if(cached!=null){picture(cached,task.image,task.token);continue;}if(!genreArtworkLoading.add(key)){pendingGenreArtwork.put(task.image,task);continue;}String apiKey=tmdbKey();io.execute(()->{String url="";try{List<Catalog.Item> examples=ContentApi.tmdbRows((task.id==-16?ContentApi.animeData(apiKey,task.type,1):ContentApi.categoryData(apiKey,task.type,task.id,1)).getJSONArray("results"),task.type,false);for(Catalog.Item item:examples){url=item.raw.optString("backdrop");if(url.isEmpty())url=item.poster;if(!url.isEmpty())break;}}catch(Exception ignored){}final String art=url;ui.post(()->{genreArtworkLoading.remove(key);if(isDestroyed())return;if(!art.isEmpty()){genreArtwork.put(key,art);if(task.token==renderVersion&&category.equals("Categories"))picture(art,task.image,task.token);ui.post(visiblePictures);}});});}
    }

    @Override protected void onDestroy(){stopPreview();if(eggAnimation!=null)eggAnimation.cancel();DirectDownloads.get(this).listener=null;++searchVersion;++loadVersion;++renderVersion;ui.removeCallbacksAndMessages(null);io.shutdownNow();imageIo.shutdownNow();pendingPictures.clear();pictureViews.clear();pictures.evictAll();super.onDestroy();}    void addToggle(LinearLayout panel,String label,String key){Switch toggle=new Switch(this);toggle.setText(label+(prefs.getBoolean(key,true)?" · ON":" · OFF"));toggle.setTextColor(prefs.getBoolean(key,true)?ACCENT:MUTED);toggle.setChecked(prefs.getBoolean(key,true));toggle.setFocusable(true);toggle.setPadding(0,dp(10),0,dp(10));toggle.setOnCheckedChangeListener((b,on)->{prefs.edit().putBoolean(key,on).apply();toggle.setText(label+(on?" · ON":" · OFF"));toggle.setTextColor(on?ACCENT:MUTED);stopPreview();});panel.addView(toggle);}
    void applyPalette(String name){Map<String,String[]> palettes=new HashMap<>();palettes.put("dark",new String[]{"#090a10","#161c29","#f4f6fc","#b0bbcc","#65e6cc"});palettes.put("light",new String[]{"#f3f5f9","#ffffff","#182130","#536174","#0a715e"});palettes.put("ocean",new String[]{"#081b29","#102c3d","#effbff","#afcad7","#79e2bd"});palettes.put("orchid",new String[]{"#18132b","#29203d","#fff5fd","#cbbbda","#efb3dc"});palettes.put("sunset",new String[]{"#101b2d","#1b2d45","#fff8eb","#bac9da","#ffc478"});palettes.put("midnight",new String[]{"#080b1a","#111936","#f7f8ff","#a8b2d8","#7c9cff"});palettes.put("ember",new String[]{"#160d0b","#2b1712","#fff5ef","#d7b2a4","#ff7a59"});palettes.put("forest",new String[]{"#09130f","#12251c","#f0fff6","#a6c6b4","#74d99f"});palettes.put("rose",new String[]{"#180d16","#30192b","#fff4fa","#d8b2ca","#ff8cc6"});palettes.put("amethyst",new String[]{"#100c1c","#211833","#faf7ff","#c6b7da","#b79cff"});palettes.put("cyber",new String[]{"#071315","#0e292d","#efffff","#9bc5c7","#32e6d3"});palettes.put("cobalt",new String[]{"#08111f","#10223c","#f4f8ff","#afc4e0","#4da3ff"});palettes.put("gold",new String[]{"#151108","#2a2110","#fff8e8","#d7c49a","#f7c948"});palettes.put("coral",new String[]{"#170f12","#2f1b20","#fff5f7","#ddb7bf","#ff7f8e"});palettes.put("aurora",new String[]{"#081315","#10272b","#f0ffff","#a7c9c7","#8ef0c7"});palettes.put("slate",new String[]{"#0c1116","#17212b","#f4f7fa","#aab8c4","#8cc8ff"});palettes.put("mocha",new String[]{"#15100d","#2b211b","#fff8f0","#d3c0b0","#d9a273"});palettes.put("goldenegg",new String[]{"#100c03","#211807","#fff8dc","#d7c58d","#ffd76a"});String[] colors=palettes.containsKey(name)?palettes.get(name):palettes.get("dark");BG=Color.parseColor(colors[0]);SURFACE=Color.parseColor(colors[1]);INK=Color.parseColor(colors[2]);MUTED=Color.parseColor(colors[3]);ACCENT=Color.parseColor(colors[4]);lightTheme=name.equals("light");}
    void switchPalette(String name){int[] before={BG,SURFACE,INK,MUTED,ACCENT};applyPalette(eggMode?"goldenegg":name);setTheme(lightTheme?R.style.AppThemeLight:R.style.AppTheme);recolor(getWindow().getDecorView(),before);for(Button b:layoutRailButtons.keySet()){android.graphics.drawable.Drawable icon=b.getCompoundDrawables()[0];if(icon instanceof LayoutIcon)b.setCompoundDrawablesWithIntrinsicBounds(new LayoutIcon(this,((LayoutIcon)icon).name,INK),null,null,null);}if(appearanceDialog!=null&&appearanceDialog.isShowing()){recolor(appearanceDialog.getWindow().getDecorView(),before);appearanceDialog.getWindow().setBackgroundDrawable(shape(BG,0));}render();}
    void recolor(View view,int[] before){int[] after={BG,SURFACE,INK,MUTED,ACCENT};if(view instanceof TextView){TextView text=(TextView)view;int current=text.getCurrentTextColor();boolean matched=false;for(int i=0;i<before.length;i++)if(current==before[i]){text.setTextColor(after[i]);matched=true;break;}if(!matched){if(current==0xFFF4F5FA||current==0xFFF4F6FC||current==0xFF182130)text.setTextColor(INK);else if(current==0xFF9DA2B5||current==0xFFB0BBCC||current==0xFF536174)text.setTextColor(MUTED);else if(current==0xFF65E6CC||current==0xFF54E5C1||current==0xFF0A715E)text.setTextColor(ACCENT);}}if(view instanceof Switch){Switch toggle=(Switch)view;toggle.setThumbTintList(android.content.res.ColorStateList.valueOf(toggle.isChecked()?ACCENT:MUTED));toggle.setTrackTintList(android.content.res.ColorStateList.valueOf((ACCENT&0xFFFFFF)|0x55000000));}android.graphics.drawable.Drawable background=view.getBackground();if(background instanceof android.graphics.drawable.ColorDrawable){int color=((android.graphics.drawable.ColorDrawable)background).getColor();for(int i=0;i<before.length;i++)if((color&0xFFFFFF)==(before[i]&0xFFFFFF)){view.setBackgroundColor((color&0xFF000000)|(after[i]&0xFFFFFF));break;}}else if(background instanceof GradientDrawable){GradientDrawable drawable=(GradientDrawable)background;Integer color=paletteShapes.get(drawable);if(color==null&&Build.VERSION.SDK_INT>=24){android.content.res.ColorStateList value=drawable.getColor();if(value!=null)color=value.getDefaultColor();}if(color!=null)for(int i=0;i<before.length;i++)if((color&0xFFFFFF)==(before[i]&0xFFFFFF)){int next=(color&0xFF000000)|(after[i]&0xFFFFFF);drawable.setColor(next);paletteShapes.put(drawable,next);break;}}if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)recolor(((ViewGroup)view).getChildAt(i),before);}
    String rawcastUsageText(JSONObject usage){long limit=usage.optLong("limit");if(limit<=0)return "RawCast usage is unavailable until the provider returns quota information.";String value="RawCast API Usage: "+usage.optLong("used")+" / "+limit+" requests used · "+usage.optLong("remaining")+" remaining · "+String.format(Locale.getDefault(),"%.1f%%",100d*usage.optLong("used")/limit);if(usage.has("reset"))value+="\nResets "+new java.text.SimpleDateFormat("MMM d, yyyy",Locale.getDefault()).format(new Date(usage.optLong("reset")));return value;}
    LinearLayout rawcastPanel(){LinearLayout panel=column();panel.setPadding(dp(20),dp(16),dp(20),dp(16));panel.addView(text("Use your own RawCast API key for downloads and RawCast streaming. Both use your limited request quota.",14,INK));EditText input=new EditText(this);input.setSingleLine(true);input.setTextColor(INK);input.setHintTextColor(MUTED);input.setHint("Paste a new API key");input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);panel.addView(input);RawCast api=RawCast.get(this);TextView saved=text(api.saved()?"rc_live_••••••••••••":"No personal key saved",13,MUTED);panel.addView(saved);TextView state=text(api.hasKey()?"Configured · Test API to validate":"Not configured",14,ACCENT);panel.addView(state);TextView usageInfo=text(rawcastUsageText(api.usage),13,MUTED);panel.addView(usageInfo);panel.addView(button("Show/hide new key",()->{input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|(input.getInputType()==129?android.text.InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD:android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD));}));panel.addView(button("Save Key",()->{try{api.save(input.getText().toString().trim());input.setText("");input.setInputType(129);saved.setText("rc_live_••••••••••••");state.setText("Key saved securely. Press Test API.");usageInfo.setText(rawcastUsageText(api.usage));}catch(Exception e){state.setText("Could not save key. Check the key and secure device storage.");}}));panel.addView(button("Remove Key",()->{api.remove();input.setText("");saved.setText("No personal key saved");state.setText("Key removed");usageInfo.setText(rawcastUsageText(api.usage));}));panel.addView(button("Test API",()->{state.setText("Testing…");io.execute(()->{try{api.test();ui.post(()->{state.setText("Connected");usageInfo.setText(rawcastUsageText(api.usage));});}catch(Exception e){ui.post(()->{state.setText(e.getMessage());usageInfo.setText(rawcastUsageText(api.usage));});}});}));panel.addView(text("Download folder: "+DirectDownloads.get(this).folder,12,MUTED));return panel;}
