    void tspKeyGuide(){LinearLayout panel=column();panel.setPadding(dp(22),dp(16),dp(22),dp(16));TextView steps=text("1. Open https://tspsearch.dev/ on your phone or computer.\n\n2. Expand ‘Advanced: copy and paste it yourself’ and wait for the site to generate your key.\n\n3. Tap Copy URL and Copy key. Copy the full key, not the shortened preview.\n\n4. Open ZeroPlay’s Downloads Settings. Paste the URL and API key, press Save, then Test Connection.\n\nDefault API URL: https://api.tspsearch.dev\nYou do not need to install Oriole for ZeroPlay.",14,INK);steps.setTextIsSelectable(true);panel.addView(steps);space(panel,14);try{com.google.zxing.common.BitMatrix matrix=new com.google.zxing.qrcode.QRCodeWriter().encode("https://tspsearch.dev/",com.google.zxing.BarcodeFormat.QR_CODE,320,320);Bitmap bitmap=Bitmap.createBitmap(320,320,Bitmap.Config.ARGB_8888);for(int y=0;y<320;y++)for(int x=0;x<320;x++)bitmap.setPixel(x,y,matrix.get(x,y)?Color.BLACK:Color.WHITE);ImageView code=new ImageView(this);code.setImageBitmap(bitmap);code.setContentDescription("Scan to open the TSP API key website on your phone");panel.addView(code,new LinearLayout.LayoutParams(dp(160),dp(160)));panel.addView(text("Scan on your phone if your TV has no browser.",12,MUTED));}catch(Exception ignored){}ScrollView scroll=new ScrollView(this);scroll.addView(panel);new AlertDialog.Builder(this).setTitle("Get your TSP API key").setView(scroll).setPositiveButton("Open website",(d,n)->{try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://tspsearch.dev/")));}catch(ActivityNotFoundException e){message("Open tspsearch.dev on your phone or computer, or scan the QR code.");tspKeyGuide();}}).setNegativeButton("Close",null).show();}
