    void downloadsPage(){DirectDownloads manager=DirectDownloads.get(this);JSONArray jobs=manager.list();downloadStats.clear();downloadBars.clear();downloadStates=downloadStateKey(jobs);sectionLabel(content,"TSP Search Downloads");content.addView(text("Download movies and episodes from healthy TSP matches. Active transfers now keep the poster, synopsis and torrent health visible while they download.",13,MUTED));space(content,10);content.addView(button("Get a TSP API key",this::tspKeyGuide));content.addView(button("Downloads Settings",this::torrentSearchSettings));space(content,18);String[][] groups={{"Active downloads","preparing","downloading","selecting"},{"Queued & paused","queued","paused"},{"Completed downloads","completed"},{"Needs attention","failed","missing","cancelled"}};for(String[] group:groups){sectionLabel(content,group[0]);int count=0;for(int i=0;i<jobs.length();i++){JSONObject j=jobs.optJSONObject(i);if(!Arrays.asList(group).contains(j.optString("state")))continue;count++;content.addView(downloadCard(j));space(content,12);}if(count==0)content.addView(text("No items.",13,MUTED));}manager.listener=()->{if(!foreground||!category.equals("Downloads"))return;JSONArray rows=manager.list();if(!downloadStates.equals(downloadStateKey(rows))){render();return;}for(int i=0;i<rows.length();i++){JSONObject j=rows.optJSONObject(i);TextView label=downloadStats.get(j.optString("id"));if(label!=null)label.setText(downloadStats(j));ProgressBar bar=downloadBars.get(j.optString("id"));if(bar!=null)bar.setProgress(downloadPercent(j));}};}
    String downloadStateKey(JSONArray jobs){StringBuilder value=new StringBuilder();for(int i=0;i<jobs.length();i++){JSONObject j=jobs.optJSONObject(i);value.append(j.optString("id")).append(j.optString("state"));}return value.toString();}
    int downloadPercent(JSONObject j){return j.optLong("total")>0?(int)Math.min(100,100d*j.optLong("bytes")/j.optLong("total")):0;}
    String downloadStats(JSONObject j){long speed=j.optLong("speed"),total=j.optLong("total"),bytes=j.optLong("bytes");return (j.optString("state").equals("preparing")?"Resolving torrent metadata":j.optString("state"))+" · "+(total>0?downloadPercent(j)+"% · ":"")+downloadSize(bytes)+" / "+downloadSize(total)+" · "+downloadSize(speed)+"/s · "+j.optInt("peers")+" peers"+(speed>0&&total>bytes?" · "+((total-bytes)/speed/60+1)+" min remaining":"");}
    AlertDialog confirmDeleteDownload(JSONObject j){AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Delete Video?").setMessage(j.optString("title")+"\n"+downloadSize(j.optLong("bytes"))+"\nThe actual local video file will be permanently deleted.").setNegativeButton("Cancel",null).setPositiveButton("Delete Video",(d,n)->downloadAction(j.optString("id"),"delete")).create();dialog.setOnShowListener(d->{dialog.getButton(AlertDialog.BUTTON_NEGATIVE).setFocusableInTouchMode(true);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setFocusableInTouchMode(true);dialog.getButton(AlertDialog.BUTTON_NEGATIVE).requestFocus();});dialog.show();return dialog;}
