    void openDownloaded(JSONObject j){File file=new File(j.optString("file"));if(!file.isFile()){render();message("Video file is missing.");return;}try{JSONObject source=new JSONObject().put("url",android.net.Uri.fromFile(file).toString()).put("mimeType",j.optString("mime","video/mp4")).put("tmdb",j.optString("tmdb")).put("type",j.optString("type","movie")).put("season",j.optInt("season",0)).put("episode",j.optInt("episode",1));startActivity(new Intent(this,PlayerActivity.class).putExtra("stream",source.toString()).putExtra("title",j.optString("title")).putExtra("key","download:"+j.optString("id")).putExtra("parent","download:"+j.optString("id")));}catch(Exception e){message("Could not open downloaded video.");}}
