    JSONObject previewData(Catalog.Item item)throws Exception{synchronized(previewMetadata){if(previewMetadata.containsKey(item.id))return previewMetadata.get(item.id);}JSONObject data=ContentApi.details(item,tmdbKey());synchronized(previewMetadata){previewMetadata.put(item.id,data);while(previewMetadata.size()>32)previewMetadata.remove(previewMetadata.keySet().iterator().next());}return data;}
