    void homepagePreview(Catalog.Item item,FrameLayout hero){if(!prefs.getBoolean("homepageTrailer",true)||!item.id.startsWith("tmdb-")||item.id.equals(hero.getTag())&&previewWeb!=null)return;hero.setTag(item.id);stopPreview();int token=previewVersion;previewTask=()->io.execute(()->{try{JSONObject data=previewData(item);ui.post(()->{if(token!=previewVersion||!foreground||detailsOpen||!getWindow().getDecorView().hasWindowFocus()||!hero.isAttachedToWindow()||!category.equals("Home"))return;String key=previewTrailer(data);if(!key.isEmpty())playPreview(hero,key,token,1);});}catch(Exception ignored){}});ui.postDelayed(previewTask,prefs.getInt("previewDelay",2000));}
